#!/usr/bin/env node
// Generated by jo-workflow (automatisation des manuels) - do not edit; changes are overwritten by sync.
//
// Loop runner: node .jow/runtime/loop.mjs <loop-name> [--system claude|opencode|codex] [--max N] [--dry-run]
// Runs the agent headless with .jow/loops/<loop-name>.md until its `until`
// check passes or max-iterations is reached.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const args = process.argv.slice(2);
const opt = (flag) => {
  const i = args.indexOf(flag);
  return i >= 0 ? args[i + 1] : undefined;
};
const name = args.find((a, i) => !a.startsWith("--") && !["--system", "--max"].includes(args[i - 1]));
const dryRun = args.includes("--dry-run");

const fail = (msg) => {
  process.stderr.write(`loop: ${msg}\n`);
  process.exit(1);
};
if (!name) fail("usage: loop.mjs <loop-name> [--system claude|opencode|codex] [--max N] [--dry-run]");

const manifest = JSON.parse(fs.readFileSync(path.join(root, ".jow", "harness.json"), "utf8"));
const loopFile = path.join(root, ".jow", "loops", `${name}.md`);
if (!fs.existsSync(loopFile)) fail(`unknown loop '${name}' (${path.relative(root, loopFile)} not found)`);

const text = fs.readFileSync(loopFile, "utf8");
const fm = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
const meta = {};
for (const line of (fm?.[1] || "").split(/\r?\n/)) {
  const kv = line.match(/^([A-Za-z0-9_-]+):\s*(.*)$/);
  if (kv) meta[kv[1]] = kv[2].trim().replace(/^["']|["']$/g, "");
}
const commands = manifest.commands || {};
const body = (fm ? fm[2] : text).replace(/(`?)\{\{\s*commands\.([A-Za-z0-9_-]+)\s*\}\}\1/g, (_, t, k) => (commands[k] ? `\`${commands[k]}\`` : `the project's ${k} command`))
  .replace(/\{\{\s*project\.name\s*\}\}/g, manifest.name);

const system = opt("--system") || manifest.systems?.[0];
if (!["claude", "opencode", "codex"].includes(system)) fail(`unsupported system '${system}'`);
const max = Number(opt("--max") || meta["max-iterations"] || 10);

const until = meta.until;
if (!until) fail(`loop '${name}' has no 'until'`);

function check() {
  if (until.startsWith("checklist:")) {
    const file = path.join(root, until.slice("checklist:".length));
    if (!fs.existsSync(file)) return { ok: false, label: until, output: `${path.relative(root, file)} does not exist yet.` };
    const open = fs.readFileSync(file, "utf8").split(/\r?\n/).filter((l) => /^\s*[-*] \[ \]/.test(l));
    return { ok: open.length === 0, label: until, output: open.length ? `Unchecked items:\n${open.join("\n")}` : "All items checked." };
  }
  const cmd = commands[until] ?? until;
  if (!cmd) fail(`command '${until}' is empty in .jow/harness.json`);
  const r = spawnSync(cmd, { cwd: root, shell: true, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  const output = `${r.stdout || ""}${r.stderr || ""}`.split(/\r?\n/).slice(-80).join("\n");
  return { ok: r.status === 0, label: cmd, output };
}

const quote = (a) => (/[\s"&|<>^]/.test(a) ? `"${a.replace(/"/g, '\\"')}"` : a);

function runAgent(prompt) {
  const extra = manifest.loop?.[system] || [];
  let exe;
  let argv;
  let input;
  if (system === "claude") {
    exe = "claude";
    argv = ["-p", ...extra];
    input = prompt;
  } else if (system === "codex") {
    exe = "codex";
    argv = ["exec", ...extra, "-"];
    input = prompt;
  } else {
    const tmp = path.join(os.tmpdir(), `harness-loop-${process.pid}.md`);
    fs.writeFileSync(tmp, prompt);
    exe = "opencode";
    argv = ["run", ...extra, "-f", tmp, "Follow the instructions in the attached file."];
  }
  const line = [exe, ...argv].map(quote).join(" ");
  if (dryRun) {
    console.log(`$ ${line}${input ? "  (prompt on stdin)" : ""}\n${prompt}\n`);
    return 0;
  }
  const r = spawnSync(line, { cwd: root, shell: true, input, stdio: [input ? "pipe" : "ignore", "inherit", "inherit"] });
  return r.status ?? 1;
}

console.log(`loop '${name}' with ${system}, until: ${until}, max ${max} iterations`);
for (let i = 1; i <= max; i++) {
  const c = check();
  if (c.ok) {
    console.log(`loop '${name}': check passed after ${i - 1} iteration(s).`);
    process.exit(0);
  }
  console.log(`\n=== iteration ${i}/${max} - check failing: ${c.label}`);
  const prompt = `${body.trim()}\n\n---\nIteration ${i} of ${max}. The check \`${c.label}\` does not pass yet. Latest output:\n\n\`\`\`\n${c.output}\n\`\`\`\n\nMake one focused change toward making it pass, then stop.\n`;
  const code = runAgent(prompt);
  if (code !== 0) fail(`agent exited with code ${code}; stopping.`);
  if (dryRun) process.exit(0);
}
const last = check();
console.log(last.ok ? `loop '${name}': check passed.` : `loop '${name}': still failing after ${max} iterations.`);
process.exit(last.ok ? 0 : 1);
